REPLACE INTO `sys_config`(`id`, `param_key`, `param_value`, `status`, `remark`) VALUES (NULL, 'cortex_yml_tmpl', '{\r\n  \"auth_enabled\": false,\r\n  \"server\": {\r\n    \"http_listen_port\": <#if port?default(\"\")?trim?length gt 0> ${port?c} <#else>10093</#if>,\r\n	\"grpc_listen_port\":10094,\r\n    \"grpc_server_max_recv_msg_size\": 104857600,\r\n    \"grpc_server_max_send_msg_size\": 104857600,\r\n    \"grpc_server_max_concurrent_streams\": 1000\r\n  },\r\n  \"distributor\": {\r\n    \"shard_by_all_labels\": true,\r\n    \"pool\": {\r\n      \"health_check_ingesters\": true\r\n    }\r\n  },\r\n  \"ingester_client\": {\r\n    \"grpc_client_config\": {\r\n      \"max_recv_msg_size\": 104857600,\r\n      \"max_send_msg_size\": 104857600,\r\n      \"grpc_compression\": \"gzip\"\r\n    }\r\n  },\r\n  <#if isMemberlistStore>\r\n	\"ingester\": {\r\n		\"lifecycler\": {\r\n		  \"join_after\": \"10s\",\r\n		  \"min_ready_duration\": \"0s\",\r\n		  \"final_sleep\": \"5s\",\r\n		  \"num_tokens\": 512,\r\n		  \"ring\": {\r\n			\"kvstore\": {\r\n			  \"store\": \"memberlist\"\r\n			},\r\n			\"replication_factor\": 1\r\n		  }\r\n		}\r\n	  },\r\n	  \"memberlist\": {\r\n		\"bind_port\": <#if gossIp?default(\"\")?trim?length gt 0>${gossIp?c}<#else>7946</#if>,\r\n		\"join_members\": [\r\n			<#list joinMemberList as joinIp>\r\n				\"${joinIp}:<#if gossIp?default(\"\")?trim?length gt 0>${gossIp?c}<#else>7946</#if>\"\r\n			<#sep>,</#sep>\r\n			</#list>\r\n		],\r\n		\"abort_if_cluster_join_fails\": false\r\n	  },\r\n  <#else>\r\n	  \"ingester\": {\r\n			\"lifecycler\": {\r\n			  \"join_after\": \"10s\",\r\n			  \"min_ready_duration\": \"0s\",\r\n			  \"final_sleep\": \"5s\",\r\n			  \"num_tokens\": 512,\r\n			  \"ring\": {\r\n				\"kvstore\": {\r\n				  \"store\": \"inmemory\"\r\n				},\r\n				\"replication_factor\": 1\r\n			  }\r\n			}\r\n		  },\r\n  </#if>\r\n  \r\n  \"storage\": {\r\n    \"engine\": \"blocks\"\r\n  },\r\n  \"blocks_storage\": {\r\n    \"tsdb\": {\r\n      \"dir\": \"/opt/nezha/cortex/tsdb\"\r\n    },\r\n    \"bucket_store\": {\r\n      \"sync_dir\": \"/opt/nezha/cortex/tsdb-sync\"\r\n    },\r\n	<#if isLocalStorage>\r\n		\"backend\": \"filesystem\",\r\n		\"filesystem\": {\r\n		  \"dir\": \"/opt/nezha/cortex/data/tsdb\"\r\n		}\r\n	<#else>\r\n		\"backend\": \"s3\",\r\n		\"s3\": {\r\n		  \"endpoint\": \"${objectStroageUrl}\",\r\n		  \"bucket_name\": \"${bucketName}\",\r\n		  \"access_key_id\": \"${accessKey}\",\r\n		  \"secret_access_key\": \"${secret}\",\r\n		  \"insecure\": <#if insecure?default(\"\")?trim?length gt 0>${insecure}<#else>true</#if>\r\n		}\r\n	</#if>\r\n  },\r\n  \"store_gateway\": {\r\n    \"sharding_enabled\": true,\r\n    \"sharding_ring\": {\r\n      \"kvstore\": {\r\n        \"store\": <#if isMemberlistStore> \"memberlist\" <#else> \"inmemory\" </#if>\r\n      }\r\n    }\r\n  },\r\n  \"compactor\": {\r\n    \"data_dir\": \"/opt/nezha/cortex/compactor\",\r\n    \"sharding_ring\": {\r\n      \"kvstore\": {\r\n        \"store\": <#if isMemberlistStore> \"memberlist\" <#else> \"inmemory\" </#if>\r\n      }\r\n    }\r\n  },\r\n  \"frontend_worker\": {\r\n    \"match_max_concurrent\": true\r\n  },\r\n  \"ruler\": {\r\n    \"enable_api\": true,\r\n    \"enable_sharding\": true,\r\n    \"rule_path\": \"/opt/nezha/cortex/rules\",\r\n    \"ring\": {\r\n      \"num_tokens\": 512,\r\n      \"kvstore\": {\r\n        \"store\": <#if isMemberlistStore> \"memberlist\" <#else> \"inmemory\" </#if>\r\n      }\r\n    },\r\n	\"alertmanager_url\":\"http://${systemConfig.alert_api}${systemConfig.alert_path_prefix}\"\r\n  },\r\n  \"ruler_storage\":{\r\n     \"backend\":\"local\",\r\n	 \"local\":{\r\n	   \"directory\":\"/opt/nezha/cortex/rules\"\r\n	 }\r\n  },\r\n  \"limits\":{\r\n	\"max_series_per_metric\": 500000000\r\n  },\r\n  \"api\":{\r\n     \"alertmanager_http_prefix\":\"/\"\r\n  }\r\n}', 1, 'cortex.yml 配置文件模板');
